def process_tg_dm_wake(payload: dict) -> bool:
    """Consume AGENT_LOOP_WAKE_TG_DM: headless agent must finish the DM task."""
    prompt = (payload.get("prompt") or "").strip()
    if not prompt:
        log.warning("[cursor-exec] skip TG_DM empty prompt")
        return False
    label = str(payload.get("task_label") or "tg-dm").strip() or "tg-dm"
    msg_id = int(payload.get("msg_id") or 0)
    lock_key = f"tg_dm_{msg_id}" if msg_id > 0 else f"tg_dm_{label}"
    full_prompt = (
        prompt
        + "\n\n铁律：必须把正文交办事项做完再停；禁止只回复「已收到/已叫醒/已知悉」。"
        + "做完后用一句话在对话里报结果即可。"
    )
    lock_path = _state_dir() / f"cursor_exec_{lock_key}.lock"
    lock_f = open(lock_path, "w", encoding="utf-8")
    try:
        fcntl.flock(lock_f.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
    except BlockingIOError:
        log.info("[cursor-exec] skip TG_DM %s (already running)", label)
        return False
    log.info("[cursor-exec] start TG_DM label=%s msg_id=%s", label, msg_id)
    try:
        append_tg_status_event(
            DEFAULT_AGENT,
            {
                "type": "progress",
                "bus_id": 0,
                "text": f"[自动执行] 私聊交办 {label} 已由 cursor-executor 接手，会干完",
            },
        )
        success = _run_work_with_retry(
            full_prompt,
            workspace=DEFAULT_WORKSPACE,
            model=DEFAULT_MODEL,
            agent=DEFAULT_AGENT,
            bus_id=0,
            continue_session=False,
        )
        log.info("[cursor-exec] TG_DM label=%s ok=%s", label, success)
        return success
    except Exception:
        log.exception("[cursor-exec] TG_DM label=%s failed", label)
        return False
    finally:
        try:
            fcntl.flock(lock_f.fileno(), fcntl.LOCK_UN)
        except OSError:
            pass
        lock_f.close()


def dispatch_wake(payload: dict, *, exec_store: dict[int, tuple[float, bool]]) -> bool:
    kind = payload.get("_wake_kind")
    if kind == WAKE_KIND_DAILY:
        return process_daily_report_wake(payload)
    if kind == WAKE_KIND_TG_DM:
        return process_tg_dm_wake(payload)
    return process_wake(payload, exec_store=exec_store)

